SELECT CASE WHEN ss.revenue >= 3800 THEN 'high' WHEN ss.revenue >= 900 THEN 'mid' ELSE 'low' END revenue_bucket, ROUND(STDDEV(i.quantity), 2) stddev_quantity, COUNT(*) row_count FROM inventory i LEFT JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id GROUP BY CASE WHEN ss.revenue >= 3800 THEN 'high' WHEN ss.revenue >= 900 THEN 'mid' ELSE 'low' END ORDER BY stddev_quantity DESC, revenue_bucket ASC;
